	(
		[ACCOUNTINGDATE],
		[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		[ADDRESSREFRECID],
		[ADDRESSREFTABLEID],
		[AUTOSUMMARYMODULETYPE],
		[AVAILSALESDATE],
