		stg.[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		stg.[ADDRESSREFRECID],
		stg.[ADDRESSREFTABLEID],
		stg.[AUTOSUMMARYMODULETYPE],
		stg.[AVAILSALESDATE],
		stg.[AWAITINGWORKFLOWTOTALSCALCULATION],
		stg.[BANKCENTRALBANKPURPOSECODE],
		stg.[BANKCENTRALBANKPURPOSETEXT],
