		stg.[ITEMBUYERGROUPID],
		stg.[ITMAGENT],
		stg.[ITMCONTRACTNUMBER],
		stg.[ITMDATE],
		stg.[ITMEXFACTORYDATE],
		stg.[ITMFREIGHTRESPONSIBILITY],
		stg.[ITMFROMPORT],
		stg.[ITMIMPORTCOSTINGVENDOR],
		stg.[ITMINTOSTOREDATE],
		stg.[ITMMEASUREMENT],
		stg.[ITMMEASUREMENTUNIT],
		stg.[ITMMENTCONFIRMATION],
		stg.[ITMOVERUNDER],
		stg.[ITMSTATUSID],
		stg.[ITMVENDACCOUNT],
		stg.[LANGUAGEID],
		stg.[LastProcessedChange_DateTime],
		stg.[LINEDISC],
		stg.[LISTCODE],
		stg.[LOCALDELIVERYDATE],
		--stg.--[LSN],
		stg.[MANUALENTRYCHANGEPOLICY],
		stg.[MARKUPGROUP],
		stg.[MATCHINGAGREEMENT],
		stg.[MCRDROPSHIPMENT],
		stg.[MULTILINEDISC],
		stg.[NUMBERSEQUENCEGROUP],
		stg.[ONETIMESUPPLIER],
		stg.[ONETIMEVENDOR],
		stg.[ORDERACCOUNT],
		stg.[OVERRIDESALESTAX],
		stg.[PACKINGSLIPAUTONUMBERING_LT],
		stg.[PARTITION],
		stg.[PAYMENT],
		stg.[PAYMENTSCHED],
		stg.[PAYMMODE],
		stg.[PAYMSPEC],
		stg.[PORT],
		stg.[POSTINGPROFILE],
		stg.[PRICEGROUPID],
		stg.[PROJID],
		stg.[PURCHASEORDERHEADERCREATIONMETHOD],
		stg.[PURCHASETYPE],
		stg.[PURCHID],
		stg.[PURCHNAME],
		stg.[PURCHORDERFORMNUM],
		stg.[PURCHPOOLID],
		stg.[PURCHSTATUS],
		stg.[REASONTABLEREF],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REPLENISHMENTLOCATION],
		stg.[REPORTINGCURRENCYFIXEDEXCHRATE],
		stg.[REQATTENTION],
		stg.[REQUESTER],
		stg.[RETAILDRIVERDETAILS],
		stg.[RETAILRETAILSTATUSTYPE],
		stg.[RETURNITEMNUM],
		stg.[RETURNREASONCODEID],
		stg.[RETURNREPLACEMENTCREATED],
		stg.[SERVICEADDRESS],
		stg.[SERVICECATEGORY],
		stg.[SERVICEDATE],
		stg.[SERVICENAME],
		stg.[SETTLEVOUCHER],
