		stg.[VATNUMRECID],
		stg.[VATNUMTABLETYPE],
		stg.[VENDGROUP],
		stg.[VENDINVOICEDECLARATION_IS],
		stg.[VENDORREF],
		stg.[WORKERPURCHPLACER]	
	FROM [staging_fo].[PURCHTABLE] stg
		LEFT JOIN [synapse_fo].[PURCHTABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[PurchId] = tgt.[PurchId] 
		
	WHERE tgt.[RECID] IS NULL
END
